from pathlib import Path
import re, html
root=Path(__file__).parent
out=root/'dist'
source=(root/'src/home.html').read_text()
countries=[('Sudan','sudan','sudan','Gold Mining & Mineral Opportunities','Gold Mining|Mineral Exploration|Geological Services|Mining Consultancy|Technical Support|Responsible Resource Development'),('Cameroon','cameroon','cameroon','Geological Intelligence & Mineral Opportunity Development','Geological Mapping|Mineral Resource Intelligence|Mining Concession Identification|License & Legal Status Verification|Field Exploration|Sampling|Geochemical Investigation|Geophysical Investigation|Exploration Target Development|Prospective Area Identification|ASM Opportunity Assessment|GIS & Digital Deliverables|Technical Opportunity Reports'),('Central African Republic','central-african-republic','fieldwork','Mineral Exploration & Mining Opportunities','Mineral Exploration|Mining Consultancy|Geological Assessment|Opportunity Identification|Technical Support|Responsible Resource Development')]
services=[('Gold Mining','gold-mining','hero','Developing opportunity.<br>Creating responsible value.','Mining Opportunity Assessment|Technical Evaluation|Mining Development Support|Operational Advisory|Safety Considerations|Environmental Considerations|Responsible Resource Development','Opportunity|Assessment|Planning|Development|Operations Support'),('Mineral Exploration','mineral-exploration','geologist','Understanding what<br>lies beneath.','Geological Mapping|Reconnaissance|Field Mapping|Rock Sampling|Soil Sampling|Stream Sediment Sampling|Trenching|Geochemical Investigation|Geophysical Investigation|Historical Data Review|Target Generation|Prospective Area Ranking','Field|Sample|Analysis|Interpretation|Target|Opportunity'),('Mining Consultancy','mining-consultancy','fieldwork','Technical insight.<br>Strategic perspective.','Technical Advisory|Geological Assessment|Opportunity Evaluation|Mining Project Evaluation|Risk Assessment|Operational Support|Investment Intelligence|Market Entry Support|Regulatory Coordination Support|Environmental Considerations|Occupational Health & Safety','Context|Assessment|Technical Review|Recommendation')]
alts={'hero':'Illustrative terraced open-pit mine','sudan':'Arid landscape south of Port Sudan','cameroon':'Rainforest in Bodiman, Cameroon','geologist':'Illustrative granite examination in Alaska','fieldwork':'Illustrative geophysical field survey in Hawaii'}
def link(text,url,cls='text-link'): return f'<a class="{cls}" href="{url}">{text} <span>↗</span></a>'
def image(name): return f'<img src="/assets/{name}.jpg" alt="{alts[name]}" loading="lazy" width="1200" height="800">'
def dropdown(label,items,base):
 return '<details><summary>'+label+'</summary><div class="dropdown"><p class="eyebrow">'+label.upper()+'</p>'+''.join(f'<a href="/{base}/{x[1]}">{x[0]}<small>{("Gold Mining & Exploration" if x[1]=="sudan" else "Mineral Exploration & Consultancy") if base=="countries" else x[3].replace("<br>"," ")}</small><span>Explore {x[0]} ↗</span></a>' for x in items)+(link('ALL SERVICES','/services') if base=='services' else '')+'</div></details>'
header=re.search(r'<header.*?</header>',source).group()
nav='<nav id="main-navigation" aria-label="Main navigation">'+''.join(f'<a href="{p}">{n}</a>' for n,p in [('Home','/'),('About','/about'),('Operations','/operations')])+dropdown('Countries',countries,'countries')+dropdown('Services',services,'services')+link('Projects','/projects','nav-link')+link('Contact','/contact','nav-link')+'</nav>'
header=re.sub(r'<nav.*?</nav>',lambda m:nav,header).replace('href="#home"','href="/"').replace('href="#contact"','href="/contact"').replace('class="menu-toggle"','class="menu-toggle" aria-controls="main-navigation"')
footer=re.search(r'<footer>.*?</footer>',source).group()
credits=re.search(r'<dialog id="credits-dialog".*?</dialog>',source).group()
paths={'home':'/','about':'/about','operations':'/operations','services':'/services','projects':'/projects','contact':'/contact','sudan':'/countries/sudan','cameroon':'/countries/cameroon','car':'/countries/central-african-republic','gold-mining':'/services/gold-mining','exploration':'/services/mineral-exploration','consultancy':'/services/mining-consultancy','project-list':'/projects'}
def routes(s):
 for a,b in paths.items(): s=s.replace(f'href="#{a}"',f'href="{b}"')
 return s
footer=routes(footer).replace('href="/">BACK TO TOP','href="#top">BACK TO TOP')
def hero(label,title,copy,img='hero'):
 return f'<section class="hero inner-hero"><div class="hero-photo" style="background-image:linear-gradient(90deg,#101419db,#10141965),url(/assets/{img}.jpg)"></div><div class="hero-content"><div class="breadcrumb"><a href="/">Home</a> / {label.title()}</div><p class="eyebrow">{label.upper()}</p><h1>{title}</h1><p class="hero-copy">{copy}</p></div><p class="image-note">Illustrative photography · See photography credits</p></section>'
def section(label,title,content,cls=''):
 return f'<section class="section {cls}"><div class="section-top"><p class="eyebrow">{label}</p></div><h2>{title}</h2>{content}</section>'
def blocks(items): return '<div class="type-grid">'+''.join(f'<article><span class="eyebrow">{i:02}</span><h3>{s}</h3></article>' for i,s in enumerate(items.split('|'),1))+'</div>'
def process(items): return section('OUR APPROACH','From knowledge to opportunity.', '<ol class="process">'+''.join(f'<li><span>{i:02}</span><h3>{s}</h3></li>' for i,s in enumerate(items.split('|'),1))+'</ol>','services')
def cta(text='Discuss an opportunity',url='/contact'):
 return '<section class="contact"><div class="contact-intro"><p class="eyebrow">PARTNER WITH GLOBAL MINO</p><h2>Natural resources.<br>Real impact.</h2><p>Connect with Global Mino to discuss mining, exploration and technical consultancy across Africa.</p><div class="actions">'+link(text.upper(),url,'button gold')+'</div></div></section>'
def panels(large=False):
 return '<div class="country-grid'+(' immersive' if large else '')+'">'+''.join(f'<a class="country {"featured" if i==0 else ""}" href="/countries/{c[1]}">{image(c[2])}<span class="country-no">0{i+1} / {c[0].upper()}</span><div class="country-body"><p>{c[3]}</p><h3>{c[0]}</h3><span class="country-link">EXPLORE {c[0].upper()} <b>↗</b></span></div></a>' for i,c in enumerate(countries))+'</div>'
def projects():
 return '<div class="project-grid listing">'+''.join(f'<article class="project" data-country="{c[1]}"><div class="project-image">{image(c[2])}<span>PROJECT PLACEHOLDER / 0{i+1}</span></div><p class="eyebrow">{c[0].upper()} · {"Gold Mining" if i==0 else "Exploration"}</p><h3>Project 0{i+1}</h3><p>Project information coming soon.</p>{link("VIEW PROJECT",f"/projects/project-0{i+1}")}</article>' for i,c in enumerate(countries))+'</div>'
pages={}
home=re.search(r'<main>(.*?)</main>',source,re.S).group(1)
home=routes(home)
for c,old in zip(countries,['sudan','cameroon','car']): home=home.replace(f'href="/contact" id="{old}"',f'href="/countries/{c[1]}" id="{old}"')
home=home.replace('href="/contact">DISCOVER GLOBAL MINO','href="/about">DISCOVER GLOBAL MINO')
for s,text in zip(services,['DISCOVER GOLD MINING','EXPLORE OUR CAPABILITIES','VIEW CONSULTANCY']): home=home.replace(f'href="/contact">{text}',f'href="/services/{s[1]}">{text}')
i=iter(range(1,4))
home=re.sub(r'<button class="text-link project-open".*?</button>',lambda m:link('VIEW PROJECT',f'/projects/project-0{next(i)}'),home)
home=re.sub(r'<footer>.*?</footer>',lambda m:footer,home).replace('href="mailto:hashim@globalmino.com?subject=Discuss%20an%20opportunity"','href="/contact"')
home=home.replace('src="assets/','src="/assets/').replace('href="/about">SCROLL','href="#about">SCROLL')
pages['/']=('Global Mino | Mining, Exploration & Consultancy',home)
about=hero('About Global Mino','Building value<br>beneath the surface.','An Africa-focused mining, mineral exploration and technical consultancy company.','geologist')
about+=section('WHO WE ARE','Mining expertise.<br>African perspective.','<div class="about-grid editorial"><div><p>Global Mino combines mining expertise, geological knowledge and technical consultancy to identify, evaluate and support mineral opportunities across Africa.</p><p>Our focus connects geological understanding with responsible development and strategic collaboration across Sudan, Cameroon and the Central African Republic.</p></div><figure class="about-image">'+image('geologist')+'</figure></div>')
about+=section('OUR PURPOSE','Turning mineral potential<br>into sustainable value.','<div class="type-grid"><article><p class="eyebrow">VISION</p><p>To position Global Mino as a trusted African partner in responsible mining, mineral exploration and technical consultancy.</p></article><article><p class="eyebrow">MISSION</p><p>To support mineral opportunities through geological knowledge, technical expertise, responsible practices and strategic collaboration.</p></article></div>','services')
about+=section('OUR VALUES','The principles beneath our work.',blocks('Technical Excellence|Integrity|Safety|Environmental Responsibility|Data Integrity|Partnership|Community Value'))+section('AFRICAN PRESENCE','Three markets. One African vision.',panels(),'operations')+cta('Discover our operations','/operations')
pages['/about']=('About Global Mino | African Mining & Exploration',about)
pages['/operations']=('Operations | Global Mino',hero('Operations','Across Africa.<br>Closer to opportunity.',"Global Mino’s operations connect geological understanding, mineral opportunities and technical expertise across selected African markets.",'sudan')+section('COUNTRY EXPERIENCE','Grounded in African opportunity.',panels(True),'operations')+cta())
for c in countries:
 name,slug,img,title,caps=c
 copy=f'Global Mino’s focus in {name} connects mineral exploration, mining opportunities and technical consultancy with responsible resource development.'
 if slug=='cameroon': copy='Gold and diamond opportunity assessment, geological exploration, concession intelligence and technical consultancy in Cameroon.'
 body=hero(name,title,copy,img)+section('OUR FOCUS',f'Geological understanding.<br>Local perspective.',f'<p class="intro-copy">{copy} Each opportunity calls for careful geological assessment, reliable information and a considered technical approach.</p>')+section('CAPABILITIES','Expertise on the ground.',blocks(caps),'services')
 if slug=='cameroon': body+=process('Geological Intelligence|Field Exploration|Data Collection|Target Identification|Opportunity Assessment|Recommendation')
 else: body+=section('PROJECTS & OPPORTUNITIES','Potential begins with understanding.','<div class="placeholder"><p class="eyebrow">PROJECT INFORMATION COMING SOON</p><p>Verified project details will be published when available.</p>'+link('EXPLORE PROJECTS','/projects')+'</div>')
 pages['/countries/'+slug]=(name+' Mining & Exploration | Global Mino',body+cta('Discuss an opportunity in '+name,'/contact?country='+slug))
body=hero('Our Services','Expertise across the<br>mining lifecycle.','Mining, exploration and technical advice connected by geological knowledge.')
body+='<section class="section services">'
for i,s in enumerate(services): body+=f'<article class="service {"reverse" if i%2 else ""}"><div class="service-image">{image(s[2])}</div><div class="service-copy"><span class="service-no">0{i+1}</span><p class="eyebrow">{s[0].upper()}</p><h2>{s[3]}</h2><p>Supporting {s[0].lower()} opportunities through geological knowledge, technical expertise and responsible practices.</p>{link("EXPLORE "+s[0].upper(),"/services/"+s[1])}</div></article>'
pages['/services']=('Services | Global Mino',body+'</section>'+cta())
for s in services:
 pages['/services/'+s[1]]=(s[0]+' | Global Mino',hero(s[0],s[3],f'{s[0]} expertise supporting informed decisions and responsible mineral opportunity development.',s[2])+section('TECHNICAL CAPABILITIES','Knowledge that supports<br>better decisions.',blocks(s[4]))+process(s[5])+cta('Discuss '+('a gold mining opportunity' if s[1]=='gold-mining' else s[0]),'/contact?interest='+s[1]))
filters='<div class="filters" role="group" aria-label="Filter projects by country">'+''.join(f'<button type="button" data-filter="{key}" aria-pressed="{str(key=="all").lower()}">{name}</button>' for name,key in [('All','all')]+[(c[0],c[1]) for c in countries])+'</div><p id="filter-status" class="sr-only" aria-live="polite"></p>'
pages['/projects']=('Projects | Global Mino',hero('Projects & Opportunities','From mineral potential<br>to progress.','Explore our country focus. Project information is awaiting verification.','sudan')+section('PROJECT DIRECTORY','Opportunities in focus.',filters+projects(),'projects')+cta())
for i,c in enumerate(countries,1):
 body=hero('Project placeholder',f'Project 0{i}',c[0]+' · '+('Gold Mining' if i==1 else 'Exploration')+' · Project information coming soon.',c[2])
 body+='<section class="section project-detail"><div>'+''.join(f'<article class="detail-block"><p class="eyebrow">{label.upper()}</p><h2>{label}</h2><p>Project information coming soon. Verified {label.lower()} details have not yet been provided.</p></article>' for label in ['Overview','Opportunity','Scope','Geology','Exploration','Technical Information','Responsible Development'])+'</div><aside><p class="eyebrow">PROJECT INFORMATION</p><dl>'+''.join(f'<dt>{a}</dt><dd>{b}</dd>' for a,b in [('Country',c[0]),('Commodity','Not confirmed'),('Project Type','Gold Mining' if i==1 else 'Exploration'),('Stage','Not confirmed'),('Status','Information coming soon')])+'</dl></aside></section>'
 body+=section('GALLERY','A perspective from the field.','<figure class="gallery">'+image(c[2])+'<figcaption>Illustrative photography. This image does not document a Global Mino project.</figcaption></figure>')+cta('Discuss this opportunity',f'/contact?project=project-0{i}')
 pages[f'/projects/project-0{i}']=(f'Project 0{i} | Global Mino',body)
def field(label,name,typ='text',required=False): return f'<label>{label}{" *" if required else ""}<input name="{name}" type="{typ}" {"required" if required else ""} maxlength="200" autocomplete="{dict(name="name",company="organization",email="email",phone="tel").get(name,"off")}"></label>'
form='<form id="contact-form"><div class="form-grid">'+field('Full Name','name',required=True)+field('Company','company')+field('Email','email','email',True)+field('Phone','phone','tel')+'<label>Country *<select name="country" required><option value="">Select a country</option>'+''.join(f'<option value="{c[1]}">{c[0]}</option>' for c in countries)+'<option value="other">Other</option></select></label><label>Area of Interest *<select name="interest" required><option value="">Select an interest</option>'+''.join(f'<option value="{x.lower().replace(" ","-")}">{x}</option>' for x in ['Gold Mining','Mineral Exploration','Mining Consultancy','Investment Opportunity','Partnership','Other'])+'</select></label><label class="full">Message *<textarea name="message" required minlength="10" maxlength="5000" rows="6"></textarea></label></div><p class="form-note">* Required fields. Your details are used to respond to this enquiry.</p><button class="button gold" type="submit">SEND ENQUIRY <span>↗</span></button><p id="form-status" role="status" aria-live="polite"></p><p class="form-note">You can also email <a href="mailto:hashim@globalmino.com">hashim@globalmino.com</a> directly.</p></form>'
pages['/contact']=('Contact | Global Mino',hero('Let’s Talk','Let’s uncover<br>the next opportunity.','Connect with Global Mino to discuss mining opportunities, mineral exploration and technical consultancy across Africa.','sudan')+'<section class="section contact-layout"><div><p class="eyebrow">GET IN TOUCH</p><h2>A conversation<br>starts here.</h2><address>Dr. Hashim Sulieman<br><span>Chief Executive Officer</span><br><br><a href="tel:+353851590630">+353 85 159 0630</a><br><a href="mailto:hashim@globalmino.com">hashim@globalmino.com</a><br><br>Alsiteen St, Building No. 29<br>Alriyad, Khartoum, Sudan<br><a href="https://globalmino.com">globalmino.com</a></address></div>'+form+'</section>')
pages['/404']=('Page not found | Global Mino',hero('404 / Page not found','A different path<br>to opportunity.','The page you requested could not be found.','sudan')+section('CONTINUE EXPLORING','Find your way forward.',link('RETURN HOME','/','button gold')))
head=source.split('<body>')[0]
for path,(title,body) in pages.items():
 desc='Global Mino — '+('mining, mineral exploration and technical consultancy across Sudan, Cameroon and the Central African Republic.' if path=='/' else title.split(' | ')[0]+'. Explore mining, geological knowledge and responsible resource development across Africa.')
 h=re.sub(r'<title>.*?</title>',lambda m:f'<title>{html.escape(title)}</title>',head)
 h=re.sub(r'<meta name="description"[^>]+>',lambda m:f'<meta name="description" content="{html.escape(desc,quote=True)}">',h)
 h=h.replace('href="style.css"','href="/style.css"').replace('</head>',f'<link rel="stylesheet" href="/pages.css"><link rel="canonical" href="https://globalmino.com{path}"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:url" content="https://globalmino.com{path}"><meta property="og:type" content="website"><meta property="og:image" content="https://globalmino.com/assets/hero.jpg"></head>')
 active=header.replace(f'href="{path}"',f'href="{path}" aria-current="page"')
 doc=h+'<body id="top"><a class="skip-link" href="#main">Skip to content</a>'+active+'<main id="main">'+body+'</main>'+('' if path=='/' else '<div class="contact">'+footer+'</div>')+credits+'<script src="/script.js" defer></script></body></html>'
 dest=out/('404.html' if path=='/404' else path.strip('/')+'/index.html' if path!='/' else 'index.html')
 dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(doc)
(out/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>https://globalmino.com{p}</loc></url>' for p in pages if p!='/404')+'</urlset>')
(out/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://globalmino.com/sitemap.xml\n')
print(f'Built {len(pages)-1} pages and 404 fallback.')
